	st := strings.Index(srcs[idx], sigs[idx])
	d := 0
	begun := false
	end := -1
	for k := st; k >= 0 && k < len(srcs[idx]); k++ {
		if srcs[idx][k] == '{' { d++; begun = true }
		if srcs[idx][k] == '}' { d--; if begun && d == 0 { end = k; break } }
	}
	if st >= 0 && end >= 0 { bodies[idx] = srcs[idx][st : end+1] }
}
norms := make([]string, 2)
for idx := 0; idx < 2; idx++ {
	out := ""
	for _, ln := range strings.Split(bodies[idx], "\n") {
		if p := strings.Index(ln, "//"); p >= 0 { ln = ln[:p] }
		ln = strings.TrimSpace(ln)
		if ln != "" { out += ln + "\n" }
	}
	norms[idx] = out
}
println("SHIPPED:\n" + norms[0])
